INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p987090-me311', 'stk-user5216', 'ME 311', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nجودة المقرر بشكل عام : ممتاز واشوفه يزيد من معرفتك في Fluid mechanics بشكل عام\n\nالمواضيع التي يغطيها المقرر : قانون برنولي + تطبيقات على قانون برنولي + قانون الاتصال او ( Continuity Equ + اللزوجه + قانون اويلر + Head loss + Dimensional Analysis و المودي تشارت + بعض الثوابت المهمه في الفلود مثل Reynolds Number\n\nالكتاب المستخدم للمقرر : ممتاز\n\nالأسئلة والأمثلة المستخدمة في المقرر : كافيه جدا وانصح فيها بقووه\n\nطريقة دراسة المقرر :\n1 - قراءة الكتاب ( واستيعاب القوانين وتعريفاتها )\n2 - فهم الامثلة وطريقة الحل واعادة حلها اذا امكن\n3 - حل اسئلة الهومورك\n4 - حل اسئلة اضافيه تشبه اسئلة الهومورك لتثبيت طريقة الحل\n\nاسئلة المياجر والفاينل ( ماتطلع عن اسئلة الهومورك ) ومره جابوا لنا سؤال بنفس الارقام بعد\n\n, وبالتوفيق ,", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-311-fluid-mechanics/120744/2", "user": "user5216", "ts": 1329314226000, "tid": 120744, "pn": 2}}', 1329314226000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1002719-me311', 'stk-user5643', 'ME 311', 'info', '{"desc": "آآآآآآآآآآه يا الفلويد ❤️ ❤️\n\nمن امتع مواد التخصص\n\nخصوصا ch 4, 5 , 7 & 10\n\nكورس حلو و مفيد ❤️\n\nمواضيعه زي ما قال الرقمي الا اني اختلف معه في مسالة الاختبارات 🤪\n\nبترمنا ما كانت حول الهوم ورك ابد 🥊\n\nاخذ الكورس مع دكتور كويس وماعليك ❤️\n\nغالبا الي يحب الثيرمو يحب الفلويد … وحتى لى ما حبيت الثيرمو ممكن تحب الفلويد …\n\nاتمنى اني افدتكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-311-fluid-mechanics/120744/3", "user": "user5643", "ts": 1331148850000, "tid": 120744, "pn": 3}}', 1331148850000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1171517-me311', 'stk-abu_abdullah', 'ME 311', 'info', '{"desc": "-\n\nماده حلوه جداً وسهلة بس تحتاج شغل وحل هومووركات وأسئلة الكتاب …\nبس نصيحة إبتعد عن الدكاتره السيئين راح يخلونك تكره المادة بكبرها …\n\nالمادة مافيها شيء جديد ، قانون برنولي ويتكرر بأكثر من طريقة وبس !!\n\nركز في تشابتر 4 و 5 و 7 و 10 … هذي هي زبدة المادة والمحصلة اللي بتطلع منها … والباقي مجرد كماليات للمادة \" من وجهة نظري \" …\n\nوبالتوفيق 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-311-fluid-mechanics/120744/5", "user": "Abu_Abdullah", "ts": 1359354689000, "tid": 120744, "pn": 5}}', 1359354689000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1202444-me311', 'stk-user7123', 'ME 311', 'info', '{"desc": "المادة كانت جدا ممتعة بالنسبة لي\n\nانا اشوف ان المادة هذه هي مزيج بين الثيرمو و الداينامكس و هي اتوقع اقرب للدينامكس بما انها تعتمد على مشتقات قانون نيوتن", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-311-fluid-mechanics/120744/6", "user": "user7123", "ts": 1364231916000, "tid": 120744, "pn": 6}}', 1364231916000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1228980-me311', 'stk-limitless', 'ME 311', 'info', '{"desc": "المادة مثل ما قالو الشباب حلوة و ممتعه , بس تحتاج مذاكرة أول بأول لأنها مترابطة , وأفضل مصدر أهو الكتاب , سهل ولا فيه هرج واجد , مع حل مسائل الهومورك وبعض البروبلم رح يكون وضعك ممتاز", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-311-fluid-mechanics/120744/7", "user": "limitless", "ts": 1369691149000, "tid": 120744, "pn": 7}}', 1369691149000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1313173-me311', 'stk-user8521', 'ME 311', 'info', '{"desc": "المادة بشكل عام من اسهل مواد الـme\n\nوالماتيريال قصير واجزاء كثيرة منه مترابطة\n\nالميجر الأول : Ch2 , ch3, جزء بسيط جدا من ch4\nزبدة الميجر الاول هو ch3, اغلب الاسئلة والدرجات تجي عليه\n\nالميجر الثاني : Ch4,5,6\n\nالفاينل : Ch4,5,6,7,8,10\n\nماتيريال الميجر الاول مرتبط بشكل بسيط بباقي المادة, لكن ماتيريال الميجر الثاني والفاينل مرتبطات ببعض جدا (خاصة 4,5,7,10)\n\nافضل طريقة للمذاكرة هي الكتاب , يعطيك الزبدة وعلى كل شي تقريبا يعطي مثال, اهم شي تفهم الفكرة الاساسية من الامثلة اللي فالكتاب بعدين دور لك اولد اكزام او شي للاستزادة فقط, ولا اعتقد ان فيه مصدر غير الكتاب اساسا\n\nالهومووركات بصراحة ما كانت جدا مفيدة , وغالبا مستواها تحت مستوى الاختبارات بكثير\n\nملاحظة : اكثر سؤال يسألونه الطلاب لبعض فهالمادة هو : هالشي معنا ولا لا ؟؟\nهالشي يجي عليه اسئلة ولا لا ؟؟\nفلذلك انتبه للاشياء اللي يركز عليها دكتورك , لان فيه اشياء تكون موجودة فالتشابتر لكن الدكتور ما يكون اطراها حتى , فتعرف اذا كان مهم ولا لا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-311-fluid-mechanics/120744/8", "user": "user8521", "ts": 1388619647000, "tid": 120744, "pn": 8}}', 1388619647000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1443586-me311', 'stk-hamd00ni', 'ME 311', 'info', '{"desc": "أنا مارح اقيم المادة هنا لأني اخذتها في الاكستشينج\n\nوكانت المواضيع نفس المواضيع اللي موجوده في سلبس المادة هنا بالزبط…\n\nلكن هناك كان الكتاب المستخدم هو Fluid Mechanics by Hibbeler طبعا اغلب طلاب الميكانيكال يعرفون هبلر وما ادراك ما هبلر (هو مؤلف كتب CE201 and CE203)\n\nمعروف جدا انه كتب هبلر ممتازة والاقزامبلز حقها واضحة…\n\nفاذا كان الكتاب المستخدم هنا سيء تقدرون تذاكرون من حق هبلر… أو تقترحون للقسم تغيير الكتاب\n\nموفقين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-311-fluid-mechanics/120744/14", "user": "Hamd00ni", "ts": 1456941179000, "tid": 120744, "pn": 14}}', 1456941179000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1449253-me311', 'stk-dyaa94', 'ME 311', 'info', '{"desc": "خذتها ف152\n\nالماده متوسطة الصعوبة …بنظري اسهل من الدينامكس بس اصعب من الثرمو باجزاءه الطيبه…مواضيعها اقرب للدينامكس الله لايرده علينا 🚬\n\nطبعا المياجر والفاينل في وادي والهوموركات واكزامبلز الكتاب في وادي ثاني…نصحيتي خذها ويه مدرس تصحيحه حلو حتى لو مايشرح…\n\nماحبيتها كثير… روقت ع ال307 اكثر…\n\nبالتوفيق يابترول…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-311-fluid-mechanics/120744/15", "user": "Dyaa94", "ts": 1463431527000, "tid": 120744, "pn": 15}}', 1463431527000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1262011-me311', 'stk-user9050', 'ME 311', 'info', '{"desc": "أضيف على كلام الإخوة التالي:\n\n322\nبالنسبة للاختبارات ركّز على الأولد إقزام والكويزيز في القسم النظري\nوبالنسبة للمسائل ركّز على الهوم وورك\n\n307\nأنا كنت أذاكر من سلايدات (سليمان باشا) وكانت ممتازة\nوأيضا إذا فهمت الهوم ورك راح تضبّط في الميجر بإذن الله\n\nالله يوفقك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-311-307-322/149181/5", "user": "user9050", "ts": 1378796694000, "tid": 149181, "pn": 5}}', 1378796694000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1045748-me311', 'stk-mesh3l_al7arbi', 'ME 311', 'info', '{"desc": "شابتر 8 فيه صعوبة شووووووووووووووووي بس … مو مرة\n\nشابتر 10 ركززززززز على\n\n***\nالـ case1, case2 and case3\nوش الفرق بين الثلاث ؟\nطبعا كلها تنطبق على التيربلنت فلو فقط\n\n1- الحالة الأولى إذا اعطاك الفلو ريت والدياميتر … وطلب الهيد لوس (مثال 10.3) حل مباشر دارسي اكويشن ومودي تشارت .\n\n2- الحالة الثانية هذي تنقسم لقسمين\n\nأ\\- إذا اعطاك الدياميتر والهيدلوس .. وطلب الفلوريت .. بهالحالة تستخدم القانون اللي موجود بالمودي تشارت \\(فووق\\) \\(المودي تشارت راح يعطونا هيا بالاختبار\\) ..شوف مثال 10.4 ب\\- إذا عطاك الدايميتر وماعطاك الهيدلوس .. وطلب الفلوريت .. بهالحالة راح تستخدم طريقة الحل الموجودة بمثال 10.5 .. تستخدم الإينيرجي إكويشن ويطلع عندك مجهولين وتسوي قس للـ f وتطلع الـ V ومن الـV تطلع Re ،ومن الـRe والـ Ks/D تستخدم المودي تشارت وتطلع f جديدة .. وترجع للأكويشن حقت الانيرجي وتطلع V جديدة .. والـ V الجديدة هذي ترجع تسوي الخطوات اللي قبل شوي لين ماتطلع لك f جديدة ثانية .. غالبا هنا تبدا تثبت قيمة الـ f وتقدر توقف ..إذا ثبتت قيمة الـ f معناته V هي القيمة الصحيحة … ومنها تطلع Q\n\n3- الحالة الثالثة إذا اعطاك الفلوريت والهيدلوس … وطلب الديامتر … هنا تستخدم قانون الشيخ دارسي… ويصير عندك مجهولين الـ f والـ D … وتسوي قس لقيمة الـ f وتبدا تسوي الجدول الموجود بمثال 10.5\nلحد ماتبدا تثبت قيمة الـ f … وبكذا يكون الديامتر الاخير هو الصحيح\n\n***وركز على الـ combined head loss equation\nوهي عبارة عن مجموع نوعين من الهيدلوسس\n\n1- هيدلوس بسبب الانحرافات والمنعطفات وإلخ(شوف جدول 10.5)…\nقانونها 10.42 صفحة 336\n\n2- هيدلوس بسبب الانبوب نفسه\nوقانونها هو نفسه قانون الشيخ دارسي\n\n*** النونراوند كونداكتز سهلة وخفيفة\n\n***وبالنسبة لـ 10.10 هو عبارة عن الكومبايند هيد لوس بس تستخدمه بمسألة يكون فيها pump head loss or turbine head loss (باستخدام جدول، شوف مثال 10.9)\n\n***البارلل بايبز مشروحة فوق .\n\nطبعا ياشباب الرد هذا بدايته كان ثلاث سطور بعدين شرحت اكثر … وبعدين اكثر … واستغليتها مراجعة والحمد لله انتبهت لاشياء كنت فاهمها غللط وتذكرت اشياء كنت ناسيها …((بالعربي لاتحسبون اني كاتب هالكلام كله لسواد عيونكم 😛 ))\nاتمنى اني وضحت لكم بعض النقاط واعذرني ياهلالي ع التأخير.\nويااااارب عسى مايكون فيه خطأ باللي كتبته\nبالتوفييييييييق وبرب ببدا اذاكر 9 و 14 مااااااااااااافتحتهم 😀D:D", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me311/126396/11", "user": "Mesh3l_Al7arbi", "ts": 1338095041000, "tid": 126396, "pn": 11}}', 1338095041000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p940121-me311', 'stk-user8509', 'ME 311', 'info', '{"desc": "انا يا جمااااااااااااااعه انلحست جدا خصوصا بهالكورس ما قد جتني حيره زي هذي تقريبا ما قد سئلت احد الا ويمدح هالدكتورين مدح جبار اللي هم وائل احمد والسررررررخي الزبده ابي الافضل من هالدكتوررررررررين بالشرح والقريد وخصوصا االقريد ابي اللي الدكتور اللي افرجه اقل شيء سي بلص وشكرا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-311/115906/1", "user": "user8509", "ts": 1322666221000, "tid": 115906, "pn": 1}}', 1322666221000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p940354-me311', 'stk-tmk2008', 'ME 311', 'info', '{"desc": "والله يا عزيزي اذا لحقت على السرخي خير وبركة لانه مشالله فاهم في المادة وتخصصه 311 ومن ناحية ما رح تلاقي اطيب منه متساهل ومرن مع الطلاب لابعد درجة مثلا (يسوي اربع او خمس كويزات ياخذ افضل ثلاثة) … بس لا تحط في بالك ابدا انه يدف او برفع الطالب في القريد انت وسكشنك ودرجات\nالباقيين مدري عنهم الصراحة لكن بالنسبة للسرخي اتكلملك عن واقع تجربة (ماخذ كورسين معه :))", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-311/115906/5", "user": "TMK2008", "ts": 1322687768000, "tid": 115906, "pn": 5}}', 1322687768000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1263373-me311', 'stk-mr-3b0d', 'ME 311', 'info', '{"desc": "انا ككنت اكره الثيرمو خاصة ثيرمو 1\n\nلكن الفلويد حبيتها,\n\nأنا كنت اذاكر من الكتاب وكان اكثر من واضح بالنسبة لي ,\n\nالتشابتر الأول : مدري وش يحس به , كله عن تحويل الوحدات, فيه كم قانون يبي لك تحفظه زي Re , لكنه سهل فلا تنخرش من اول نظره.\n\nالتشابتر الثاني: يتكلم عن الفيسكوسيتي والسيرفس تينشن وكم شغلة بسيطة لكن منوعة\n\nالتشابتر الثالث: يتكلم عن الفورسيز الي تصير في الفلويد, ذاكر القيتز زييييين تراها فيها لحسة شوي لكنها 100% تجي بالاختبار\n\nأهم شيء انت اكسر الحاجز حق :(وييين صعبة) ,(مافي امل افهمها), (باكرهها زي ما كرهت الثيرمو)\n\nلأنك لين بديت فيها تراها تخوف إذا ما خشيت فيها صح لكنها سهلة جداً إذا بديت تذاكر", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-311/149500/2", "user": "mr-3b0d", "ts": 1379069030000, "tid": 149500, "pn": 2}}', 1379069030000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p977422-me311', 'stk-mechanical_boy', 'ME 311', 'info', '{"desc": "بالنسبه لل Me 311 لازم تكون فاهم الكونسبت عشان تقدر تحل اي مساله , لازم تكون فاهم الامثله الي بالكتاب وثم طبق عالهومورك . في الترم الي راح 111 اذكر ان اسئلتهم دايم تكون مشابهه للامثله اذكر ميجر ون جابو مثال نسخ لصق وواحد من الهومورك برضو نسخ لصق وبرضو اذا عندك وقت حاول تذاكر الاسئله في نهايه كل شابتر لانهم يجيبون منها بالمياجر والفاينل نسخ لصق عالعموم الفلويد امتع كورس ميكانيك مر علي لحد الان ممتع جدا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me311-me309/119350/4", "user": "Mechanical_Boy", "ts": 1328018166000, "tid": 119350, "pn": 4}}', 1328018166000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p470817-me311', 'stk-ba_de_r', 'ME 311', 'info', '{"desc": "بيني و بينك\n\nمادة الهيت ترانسفر الافضل فيها حسب رأيي محمد عنتر\n\nالديني اعرف واحد اخذ معاه me311 مره مايمدحه يقول المياجر ماعطانا كم اخذنا فيه يقول لين نهاية السمستر و ماعرفت اي شيء الا بالفاينل قريد على ما اظن و برضو ينتقد اسلوبه بالمعامله\n\nاما القحطاني يمدحونه من ناحية انه يعطي قريد لكن يكرررف من النوع اللي يشكل قروبات و يعطي مهمات و كذا واذا ماني غلطان مايعطي كويزز و يعطي احيانا محضرات مسائيه\n\nاما النكله(النخله؟) هذا ما اعرف عنه شيء للأسف", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/083-091/72840/371", "user": "Ba_De_R", "ts": 1254841714000, "tid": 72840, "pn": 371}}', 1254841714000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p345156-me311', 'stk-user2552', 'ME 311', 'info', '{"desc": "انا درسني … توفيق اياندي\n\nT AYINDE\n\nفي الـ me -311\n\nالدكتور … شرحه ممتاز و واضح … لكنه اللهجة افريقية\n\nعشان كذا … لازم تتعود\n\nغير كذا … اذا ركزت معاه في المحاضرة … تطلع فاهم المادة بشكل سليم\n\nبشرط تكتب معاه … كل صغيرة و كبيرة … مع الملاحظات\n\nالكويزات :::: متوسطة … اذا ذاكرت من النوت … تجيب درجة حلوة\n\nالمياجر ::: ايضا متوسطة … اذا حليت الهوموورك … و فهمته … تجيب قريد طيب\n\nيعني باختصار … النوت + الهومورك … = انت في السليم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68947/17", "user": "user2552", "ts": 1230570439000, "tid": 68947, "pn": 17}}', 1230570439000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
