INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p908851-me311', 'stk-user4567', 'ME 311', 'srcU', '{"html": "ملف الاكسل في المرفقات …<br><br>موفق …<br><br>​<span data-fid=\"stk-f908851-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f908851-0": {"name": "problem_correlation_guide.zip", "v": "data:application/zip;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-311/112705/7", "user": "user4567", "ts": 1317026151000, "tid": 112705, "pn": 7}}', 1317026151000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1124637-me311', 'stk-ghetto', 'ME 311', 'srcU', '{"html": "🤠<br><br>​<span data-fid=\"stk-f1124637-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f1124637-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f1124637-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f1124637-3\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1124637-0": {"name": "ME311_061_chapter4.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/1d62d6602cc6d07095e294a03041f1a96b9b8e177fbdcbd74d5276e80c35b38e"}, "stk-f1124637-1": {"name": "ME311_061_chapter5.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/826b9921023352f5ae43ec44cc3785106bfb2adee76e17146ff88d8f7fc85d7e"}, "stk-f1124637-2": {"name": "ME311_061_chapter6.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/2e7385649484e233980b97007606b166b2a73f26a1366c2d9b8791dc893f0ed1"}, "stk-f1124637-3": {"name": "ME311_061_chapter7.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/4c1a493819b9f017041f4d2f3d97ac6494fac0cbde7e1a46561b14d48abe6a7d"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me311/135058/4", "user": "ghetto", "ts": 1353951387000, "tid": 135058, "pn": 4}}', 1353951387000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1152715-me311', 'stk-mezo.m', 'ME 311', 'srcP', '{"html": "هذا الي حصلته من اولد فاينالز<br>بالتوفيق يا شباب … دعواتكم<br><br>​<span data-fid=\"stk-f1152715-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f1152715-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f1152715-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1152715-0": {"name": "term 102 final exam.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/0bf3c06d90d2ee69d55d2919bcbbbb6bd3ccf848439c4897ef715f34ab6eaf44"}, "stk-f1152715-1": {"name": "New WinRAR ZIP archive.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/7f1bfec7c3b0d8cc06ba213fae3a26b2f6222804de94394a781026368f66e973"}, "stk-f1152715-2": {"name": "New WinRAR ZIP archive (2).zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/b14c0198bac1dac8e96f8b650bee15cf2f712cbd42324ab0079e406c78af53a3"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me311/126396/53", "user": "mezo.m", "ts": 1357068133000, "tid": 126396, "pn": 53}}', 1357068133000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1194344-me311', 'stk-d.e.99', 'ME 311', 'srcP', '{"html": "دعواتكم:)<br><br>​<span data-fid=\"stk-f1194344-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1194344-0": {"name": "homeworks.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/66dfec2ae44324f47c639a12f6afa8824c7dab537ef29017e3bb20cdd7510695"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-311/141271/7", "user": "D.E.99", "ts": 1362315622000, "tid": 141271, "pn": 7}}', 1362315622000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p941264-me311', 'stk-me.me.me', 'ME 311', 'srcP', '{"html": "السلوشن للهوموركات<br><br>هذي الاسئلة حقت الهومورك والسلوشن ch 5,6,7<br><br>​<span data-fid=\"stk-f941264-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f941264-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f941264-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f941264-3\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f941264-0": {"name": "HW05_Solution.pdf", "v": "data:application/pdf;base64,"}, "stk-f941264-1": {"name": "HW06_Solution.pdf", "v": "data:application/pdf;base64,"}, "stk-f941264-2": {"name": "HW07_Solution.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/777e0869cd768c2af1bd90dc7f5d7ef41a42cf607d7409b9957e4a0e3f7cba66"}, "stk-f941264-3": {"name": "HW08_Solution.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/3ac58420efb540c6a03d8b921aa30bc0f9493206f249030782fe38b129c012f4"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-311-old-exam/116003/7", "user": "ME.ME.ME", "ts": 1322831643000, "tid": 116003, "pn": 7}}', 1322831643000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1174639-me311', 'stk-mostafa-2008', 'ME 311', 'srcU', '{"html": "Me 311<br><br>تفضل<br><br>​<span data-fid=\"stk-f1174639-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>🌹 🌹 🌹<br><br>موفق<br><br>ME311_syllbaus 122.pdf (101 KB)", "files": {"stk-f1174639-0": {"name": "ME311_syllbaus 122.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/825c30cc63cb0f3ed4ff575ec96f69dc77df80bee20b361a878cef534fd25c5b"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me311-syllubus-and-slides/139592/2", "user": "Mostafa-2008", "ts": 1359733792000, "tid": 139592, "pn": 2}}', 1359733792000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p961333-me311', 'stk-_286', 'ME 311', 'srcP', '{"html": "ســـــــــــــــــــــــــــــــــــم ياجميــــــــــــــــــــــــــــــــــــل<br><br>هذا الملــــــــــــف فيه تصوير للفاينل وأنت عاد اللي ماتلقاه في الملف إسحب عليه<br><br>وأصـــــــــــــــــــــــدق الدعوات من قليبك تكفــــــــــــى<br><br>​<span data-fid=\"stk-f961333-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f961333-0": {"name": "Preparation-Final Exam  -111.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-311/117687/2", "user": "_286", "ts": 1325968105000, "tid": 117687, "pn": 2}}', 1325968105000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p964222-me311', 'stk-safety280', 'ME 311', 'srcP', '{"html": "وعليكم السلام ورحمة الله وبركاته 🙂<br><br>The exam will be a closed book exam with no formula sheets.<br>The exam will cover all course material except for the following:<br>a) Hydrostatic forces on plane and curved surfaces (Sections 3.4 and 3.5).<br>b) Buoyancy and stability of immersed and floating bodies (Sections 3.6 and 3.7).<br>c) No numerical-type problems will be given on Chapter 9.<br>…<br>باقي التفاصيل في الملف المرفق، فالكم التوفيق 🌹<br><br>​<span data-fid=\"stk-f964222-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f964222-0": {"name": "ME311.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-311/117687/9", "user": "safety280", "ts": 1326247305000, "tid": 117687, "pn": 9}}', 1326247305000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1101049-me311', 'stk-user4626', 'ME 311', 'srcP', '{"html": "رفعت الواجب<br>الي يحب يفزع ممكن يتفضل<br><br>​<span data-fid=\"stk-f1101049-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1101049-0": {"name": "HW # 3.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/3f2bdc1c2cbd4c33b27ea79fdc99f47432faccc51b8451acc6ef9dadb492fae1"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-311/132611/13", "user": "user4626", "ts": 1349019985000, "tid": 132611, "pn": 13}}', 1349019985000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1042198-me311', 'stk-mesh3l_al7arbi', 'ME 311', 'srcP', '{"html": "تفضل الملف بالمرفقات ياعزيزي،<br><br>ع فكرة عدد الأسئلة بيكون نفس عدد اسئلة المياجر 🙂<br><br>وبالتوفيق<br><br>​<span data-fid=\"stk-f1042198-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1042198-0": {"name": "ME311.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fluid311-final/126064/2", "user": "Mesh3l_Al7arbi", "ts": 1337733412000, "tid": 126064, "pn": 2}}', 1337733412000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1102165-me311', 'stk-mters177', 'ME 311', 'srcU', '{"html": "هذي الملفات الي قال عنها ابو شوق<br>للي مافتح معه الرابط<br><br>الملفات بالمرفقات<br><br>دعواتكم لي بالتوفيق في المياجر 😭<br><br>​<span data-fid=\"stk-f1102165-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f1102165-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f1102165-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f1102165-3\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f1102165-4\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f1102165-5\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f1102165-6\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1102165-0": {"name": "ME311_061_chapter1.doc", "v": "data:application/msword;base64,"}, "stk-f1102165-1": {"name": "ME311_061_chapter2.doc", "v": "data:application/msword;base64,"}, "stk-f1102165-2": {"name": "ME311_061_chapter3.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/0c0ae4551eeb3cd887103e4f654a6804a2839fd9364d3d19cb6efea55b2ac395"}, "stk-f1102165-3": {"name": "ME311_061_chapter4.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/1d62d6602cc6d07095e294a03041f1a96b9b8e177fbdcbd74d5276e80c35b38e"}, "stk-f1102165-4": {"name": "ME311_061_chapter5.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/826b9921023352f5ae43ec44cc3785106bfb2adee76e17146ff88d8f7fc85d7e"}, "stk-f1102165-5": {"name": "ME311_061_chapter6.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/2e7385649484e233980b97007606b166b2a73f26a1366c2d9b8791dc893f0ed1"}, "stk-f1102165-6": {"name": "ME311_061_chapter7.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/4c1a493819b9f017041f4d2f3d97ac6494fac0cbde7e1a46561b14d48abe6a7d"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/132772/15", "user": "mters177", "ts": 1349198896000, "tid": 132772, "pn": 15}}', 1349198896000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6685-me311', 'stk-user6685', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f98186", "n": "Dr. Hassan M. Badr", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السلام عليكم\nأخذت مع الدكتور حسن ME 311 ترم 121\n\nالتحضير\nكان بداية كل كلاس وبعد اول 5 دقايق احتمال يمنعك من الدخول\n\nالشرح\nمن افضل الدكاترة اللي مروا علي بالجامعة … يثقفك كمهندس بغض النظر عن القريد\n\nالكوزات\nبالعادة الكوزات عليها %10 يخليها %15 … (+ %5 من الواجبات )\nالكوزات صعبة والافرج كان 9 من 20 …\nفيه شي مهم هنا لازم تعرفه المدرس يحسب درجة كل طالب في الكوزات بدون اي اعتبار للافرج … يعني تجيب 5 من 20 في ثلاثة كوزات … تاخذ 5 من 20 مافيه نظام افرج\n\nالمياجر\nكانت كومن … واحد من زملائي اخذ المادة في ترم 121 واخذها في ترم 122 ونجح بسهولة … المدرس كان يضع اغلب الاسئلة وكانت ثقيلة نوعا ما و كلها Integration\n\nالقريدات والتصحيح سيئ وفيه غيره افضل بكثير\nعموما المدرس هذا خذ منه علم … ولا ترجي قريد …\nيكره الاسئلة البسيطة او الغبية ويكون رده احيانا محرج …\n\nانصح الدوافير ومن يحب ياخذ علم ولو على حساب القريد فيه …\n(المدرس لايظلم ولكن صارم جدا)\nبالتوفيق ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1379726-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-hassan-m-badr/98186/11", "user": "user6685", "ts": 1402680012000, "tid": 98186, "pn": 11}}]}', 1402680012000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-amat_24-me311', 'stk-amat_24', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f98192", "n": "Dr. Bekir Sami Yilbas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "semester: 101\ncourse ME 311\n\nالتحضير : يومي في آخر الكلاس ينادي الاسماء ويسجل، بس ظني انه مو متشدد او ما يحاسب عليه ولا عمره علق على التاخير او كثرة الغيابات\n\nطريقة الشرح :كتابة على السبورة، وانصح بشدددة انك تكتب وتسجل معاه كل شي يقوله، يحل مسائل غير عددية يعني يشتق صيغة المطلوب بدون ارقام، المسائل اللي يحلها جدا مهمة وبعضها تقريبا تجي في المياجر لكن باختلاف المطلوب\n\nالكويزات :\n\nالمياجر:كومن\nالفاينلات :كومن\n\nالقريد النهائي:A\n\nالصوت: واضح، لهجته غريبة شوية لكن واضحة، احيانا يحاول يتكلم عربي (الدكتور تركي) لكنه ما يعرف اكثر من 10 كلمات على ما اعتقد\n\nإضافات : الدكتور جدددا اخلاق عالية\n\nاعطانا بروجكت سهل في الحسابات لكن صعب في الرسيرش، وطلبه قبل نهاية السمستر ب3 او 4 اسابيع وآخر يوم تسليم يوم السبت في آخر اسبوع، اعتقد سمعت بعض الشباب من سكاشن ثانية يقولو الدكتور اعطاهم بروجكت آخر اسبوع شغلهم عن المذاكرة للفاينلز\n\nكويزاته بعضها صعبة وبعضها سهلة، على ما اتذكر اعطى الشباب اللي مجموع كويزاتهم منخفض كويز زيادة آخر اسبوع، فرصة للتعويض\n\nاعتقد انه يدف او يدف اللي يتعبو على البروجكت\nانا اخذت 4 قريدات فوق اللي متوقعه (ميجر 1 ما ادري عن درجته غبت في اليوم اللي اعطى فيه الدرجات وخفت اساله لاني جايب العيد، ميجر 2 جبت تحت الآفرج، والافرج كان تحت ال50)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p782918-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-bekir-sami-yilbas/98192/3", "user": "amat_24", "ts": 1297021519000, "tid": 98192, "pn": 3}}]}', 1297021519000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8551-me311', 'stk-user8551', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f98192", "n": "Dr. Bekir Sami Yilbas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 311 - Term 131\n\nالتحضير : ما يحضر دائما ، و إذا حضر يكون تحضيره بنص المحاضرة أو آخرها (يعني ما فيه ليت) ، الكلاسات اللي أخذ فيها تحضير تقريبا 40% من الترم كامل ، ما يحضر بفترة المياجر . يسمح بالحضور مع سكشن ثاني.\nيخصم عالغياب (الحضور عليه 3 درجات من الكلاس وورك).\n\nالشرح : يشرح و هو يكتب عالسبورة ، خطه واضح لكنه صغير و يحشر الكلام و الرسوم بالسبورة ما تدري وين إبتدى و و وين إنتهى ، طبعا أغلب اللي يكتبه عالبسورة إشتقاق في إشتقاق ، نادر ما يكتب أرقام عالسبورة (يحل المسألة بالفاريابلز و يخلي التعويض عليك) ، بصراحة ما أعجبتني طريقة شرحه أبد ، كلاسه ما فيه أي تفاعل (يجيب النوم) ، الدكتور يشرح و كأنه يسمع كلام حافظه من أول ، نفس نبرة الصوت ما تتغير ،.و ما يسأل الطلاب بوسط المحاضرة عن الدروس السابقة.\nأغلب المسائل اللي يحلها تكون أمثلة الكتاب (ما فيه داعي تكتب معه هذا النوع من المسائل) ؛ لكن فيه مسائل مهمة جدا مهيب موجودة بالكتاب يأخذها من إختبارات قديمة و يحلها ثم يجيبها بالكويزات و بعضها جانا بالمياجر (هنا ضروري تكتب معه).\nيبتدي المحاضرة بوقتها بالضبط و ينهيها قبل الوقت المحدد بدقيقتين أو ثلاث.\n\nالكويزات : عليها 12 درجة ، أعطانا ثلاث كويزات و أخذ أفضل إثنين (يعني كل كويز عليه 6 ) ، الطلاب اللي كان أفرج أفضل كويزين عندهم أقل من 60% أعطاهم كويز رابع للتحسين.\nالكويزات ما كانت صعبة ، غالبا ما تكون من الأشياء اللي يشرحها بالكلاس (غير موجودة بالكتاب) ، و بعضها يكون من أمثلة الكتاب مباشرة.\n\nالبروجكت : البروجكت عليه 3% ، و اللي يبدع فيه راح يعطيه بونص 2% ، الدكتور يهتم كثيـــر بالبروجكت و يمكن يرفعك قريد لو عرف إنك مهتم (تروح له المكتب و تسأله كيف نجيب هذي وكذا) ، سؤال البروجكت كان سهل لكنه طويل و يحتاج بحث واجد (كيف تجيب الستاندرد سايز – أسعار القطع – التكلفة الكاملة مع شغل اليد … إلخ).\n\nالمياجر و الفاينلات : كومن.\n\nالتصحيح : لو كان أغلب الطلاب حلو السؤال بشكل صحيح فراح يحاسب بشدة عليه و لو أغلب الطلاب جابو العيد بسؤال معين راح يدف السكشن كامل بذاك السؤال ، لكن بشكل عام الدكتور شديـــد جدا بالتصحيح و يهتم بالجواب النهائي ، لو كانت كل خطوات حلك صحيحة لكن جوابك النهائي بعيد عن الجواب الصحيح راح يخسف فيك (حتى لو كان الخطأ تافه مثل إنك نسيت تحول الملي أو شئ زي كذا) .\nأذكر فيه سؤال كان عليه 25 درجة و كل خطوات حلي كانت صحيحة اللهم بأول خطوة بس بدال ما أضرب قسمت على كوساين الزاوية (الحل كله يعتمد على هذي القيمة) ، أعطاني 5 من 25 !! المعروف عن هذا الدكتور إنه يغبن في التصحيح.\n\nالقريدات : قالنا ببداية الترم إذا فيه أحد خبص بالميجر الأول ثم شد حيله و جاب قريدات طيبة بالميجر الثاني و الفاينل ، راح أتغاضى عن درجته بالميجر الأول ، أنا أشهد إنه قال كلمته و وفى بها :\nالميجر الأول = 65\nالميجر الثاني = 92\nالفاينل = 94\nو أعطاني A+\nبصراحة ما قد سمعت أحد إشتكى من قريداته ، رفعنا بالأخير الله يجزاه خير ، السكشن اللي أنا فيه ثلاثة أخذو A+\n\nإضافات :\n- الدكتور تركي الجنسية ، و مؤلف كتاب عن تقنية الليزر (هذي صورة لغلاف الكتاب).\n- دايم متواجد بمكتبه (يحضر من 6 الصبح).\n- هو و دكتور سيد زبير فقط اللي حصلو على لقب “بروفسور مميز” من القسم.\n- أخلاقه عالية جدا و دايم مبتسم ، ما ينسى طلابه اللي درسهم ، قالنا أكثر من سالفة عن مهندسين (كانو طلابه من أول) يجون يستشيرونه بالفلويد ، بإختصار الدكتور نابغة بهذا المجال.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1318514-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-bekir-sami-yilbas/98192/8", "user": "user8551", "ts": 1389537975000, "tid": 98192, "pn": 8}}]}', 1389537975000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9213-me311', 'stk-user9213', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f98192", "n": "Dr. Bekir Sami Yilbas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 311 - 161\n\nالتحضير :\n\nحسب المزاج يعني مو دايم ويكون اخر الكلاس\n\nطريقة الشرح :\n\nجيدة جدا وما يشرح كل بس يتطرق لكل النقاط المهمه , يشرح طريقط المسائل بس ما يحلproblems numerical اكتب اللي يقولك مهم.\n\nالكويزات :\n\nمسائل اولد اقزامز و يعطي كويز بونص للي معيد\n\nالمياجر:\n\nكومن\n\nالفاينلات :\n\nكومن\n\nالقريد النهائي:\n\nA\nالصوت:\n\nمنخفض و حاول تجلس قريب\n\nإضافات :\n\nالدكتور شرحه حلو بس مهب كافي لازم تعتمد على نفسك وتذاكر من الكتاب و تحل مسائل بنفسك .اخلاقه عاليه و يفيدك بس عنده غموض فتوزيع الدرجات و ايضا التصحيح يعني يقول لو السؤال قليل اخطوا فيه بخسفك ولو كثير عيدوا فيه بنقص شوي او بعطي بونص. فالفاينل قريد اشوفه اعاطني حقي مع تحفظي انه ما علمنا الدرجات حقت الفاينل و لا تقسيم الدرجات اذا حصلك افضل منه مثل سعد منصور نزل معه بس يبقى خيار جيد.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467258-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-bekir-sami-yilbas/98192/14", "user": "user9213", "ts": 1485739466000, "tid": 98192, "pn": 14}}]}', 1485739466000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khdsa2022-me311', 'stk-khdsa2022', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f98192", "n": "Dr. Bekir Sami Yilbas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : BEKIR YILBAS\nالمادة: ME 311\nمنقول عبر واااتس اب\nالفصل الدراسي: 191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : اول الترم كان يحضر يومياً نهاية الكلاس او نصه , بعد تقريبا شهر او اكثر صار ما يحضر الا قليل حسب عدد الطلاب الحاضرين (اذا كانوا كثار ما حضر و العكس)\nطريقة الشرح : يشرح بالكلام و يكتب على السبورة ( بعد شهرين بدأت اطفش من كلامه واكتفيت بالكتابة وراه مع فهم قليل). لكن تشابتر ١٠ استخدم السلايدات، يحب يشرح من فين جاء القانون و يعطي امثلة واقعية عليه.\nالكويزات : كويزاته سهلة و من اللي يتكبه في الكلاس و اذا سلمت الورقة وعندك غلط يقول لك ان فيه غلط ويرجعك تصححه و يساعد كثير فيها . ما يحب يشوف احد ينقص في الكويزات\nالمياجر: تصحيحه يختلف حساب اداء الطلاب في السؤال ؟ مثلاً الميجر يتكون من ثلاثة أسئلة. اذا مثلاً اغلب الطلاب جايبين العيد بالسؤال الأول يحاول انه ما يخصم واجد في السؤال الأول منهم ومن هذه الناحية هو ممتاز لكن اذا الطلاب اغلبهم حلوا السؤال الثالث صح يصير يخصم بشكل قوي على الغلط في السؤال الثالث فانتبهوا\nالفاينلات : ما شفت ورقتي بعد الإختبار لكن الظاهر يتبع نفس الأسلوب\nالقريد النهائي: متحير بين B+\nالصوت: صوته ضعيف\nإضافات : الدكتور ما يحب احد يراجعه على درجته في المياجر لأنه متساعد جداً في التصحيح كذا اذا حاب تراجعه راح يخصم منك كل درجة مزودها", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518746-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-bekir-sami-yilbas/98192/15", "user": "Khdsa2022", "ts": 1578208665000, "tid": 98192, "pn": 15}}]}', 1578208665000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-me311', 'stk-guest', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f98200", "n": "Dr. Mohammad Al-Qahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "me311 ترم 201 “ترم الاون لاين”\n\nالتحضير : الزامي بس قلبه اختياري اخر اسبوعين\nوالتحضير من البروقرام تبع البلاك بورد\nطريقة الشرح : الدكتور في الشرح اسطوري بمعنى الكلمة وهالشيء يشهد فيه مو بس طلابه … حتى طلاب باقي الدكاترة من خلال متابعتهم لقناته على اليوتيوب … ويحب يشرح المعاني الفيزيائية للقوانين وكيف نستخدم هالشغلات في العمل الميداني\nالكويزات : 8 كويزات عليهم 50% وكل واحد يقول الزين عندي … كان يشكل بين متوسط وصعب … مشكلتها في الاون لاين يعطينا وقت اقل من الطبيعي بزيادة بحجة “لا تغشوا” … وكانت الكويزات عبارة عن سرعه في الحل اكثر من كونك فاهم او لا… الوقت الضيق يسبب ضغط يخليك ما تفكر مضبوط في الكويز وتغلط اغلاط ما تدري كيف غلطتها … + بالنهاية عطانا تيست من 10% زيادة عبارة عن اسئلة قصيرة MCQs … كان القروب بعد الاختبار عبارة عن “انا ما مداني احل الا نصه … حليت 6 اسئلة وخلص الوقت … الخ”\nالمياجر: فيه مد تيرم من 15% ومو كومن … عباره عن ثلاثه اجزاء … MCQs يميل للسهوله … سؤال متوسط … سؤال صعب ووقته قصير\nالفاينلات : 4 اسئلة مستواهم معقول لكن الوقت تعبنا … اغلب الطلاب عارفين السؤال وخابزين فكرته بس ما مدى نحله كامل\nالصوت: ممتاز وواضح وشرحه عربي مع مصطلحات التخصص بالانجليزي\nإضافات : الدكتور مهتم بفهمنا بشكل كبير ويتمنى لنا الخير الله يعطيه العافيه … لكن طريقته في الاختبارات في ترم الاون لاين كانت مستفزه جدًا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527486-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-al-qahtani/98200/42", "user": "Guest", "ts": 1609592035000, "tid": 98200, "pn": 42}}, {"id": "stk-dr-f98192", "n": "Dr. Bekir Sami Yilbas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Me311 ترم ٢٠١\n\nالتحضير : يقول انه ياخذ التحضير من زوم\nطريقة الشرح : بالبداية كنت اركز معه لكن ما اعجبني و سحبت عليه\nالكويزات : كانت ثوريتيكال و كانت صعبة الصراحة\nالمياجر: متوسطة الى صعبة\nالفاينلات : صععععب\nالقريد النهائي: C\nالصوت: واضح\nإضافات : خله اخر خياراتك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527552-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-bekir-sami-yilbas/98192/17", "user": "Guest", "ts": 1609775232000, "tid": 98192, "pn": 17}}]}', 1609592035000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-wil.e-me311', 'stk-wil.e', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f98192", "n": "Dr. Bekir Sami Yilbas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME311 ترم ٢٠١\n\nالتحضير : يقول انه يحضر بس انا متاكد انه ما يحضر ابدا\n\nطريقة الشرح : صراحة بعض المواضيع شرحها بطريقة حلوة والبعض الآخر لا، عالعموم مقاطع الدكتور محمد شايع تغني عن الدكتور\n\nالكويزات : ثيوري عميق جدا، وللاسف مرة علق علي البلاكبورد وانا اختبر الكويز وصفقني البلاك بورد 2/10 وريته وقت الاختبار انه علق وقال ما اقدر اسوي لك شي بس يله حمدلله :exploding_head:\n\nالمياجر: الميد عن نفسي شفته سهل نوعا ما بشرط انك ترجع لمقاطع القحطاني تحل وتجرب نفسك\n\nالفاينلات : صععععب كان جدا جدا جدا و سيء وغيروا درجته من 30 ل35 واحنا اخر من يعلم\n\nالقريد النهائي: B\n\nالصوت: واضح\n\nإضافات : جدا ما يعرف للتكنولوجيا فلا تتوقع يفيدك بالمشاكل التقنية اللي تصير من ناحية تعليقات او مشاكل رفع لذلك حاول ما تطيح بمشاكل زي كذا معه، تصحيحه لا بأس به نوعا ما", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529927-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-bekir-sami-yilbas/98192/18", "user": "wil.e", "ts": 1620549999000, "tid": 98192, "pn": 18}}]}', 1620549999000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5643-me311', 'stk-user5643', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f98194", "n": "Dr. Abdelsalam Al-Sarkhi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 311\n\nTerm 102\n\nالتحضير : يمرر ورقه و لا يشيك عليها …\n\nالشرح : سبوره سلايدات … و كل ما يخطر على بالك\n\nوالله يا جماعه ينبه على شغلات … تجي بالميجر\n\nركز بالشرح نصيحه …\n\nالتصحيح : حقك …\n\nالكوزات : عطانا 6 و حسب 3 … مستواها وسط الى سهل\n\nاضافات : قمه في الاخلاق 🙂 رووووعه في الشرح اعطيه A … متساعد و متعاون …\n\nانسان فااااااااااااااااااااااهم فاهم ما شاء الله عليه احمد الله اني توفقت و اخذت كورس معه .. متساعد في القريد النهائي الله يحفظه و يكثر من امثاله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p970431-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdelsalam-al-sarkhi/98194/12", "user": "user5643", "ts": 1326886242000, "tid": 98194, "pn": 12}}]}', 1326886242000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullatif1994-me311', 'stk-abdullatif1994', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f98194", "n": "Dr. Abdelsalam Al-Sarkhi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المادة: Me311\nالترم: 142\nالتحضير : التحضير شبه يومي … وما اتوقع انه يخصم على الغيابات …\nطريقة الشرح : شرحه يكون من السلايدات واذا خلصت كل شبتر يحل مسائل عليه … طبعا شرحه مش ولابد يعني يشرح بس نبرته ماتخليك تتحمس معاه …\nالكويزات : كويزاته كان بعضها صعب وبعضها سهل … عنده 6 كويزات وياخذ افضل 3 ,\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B+\nالصوت: واضح\nإضافات : الدكتور طيب ومعاملته في القمه … والصراحه يدفك درجات ولا ينقصك … طبعا البروجكت مايعطي اقل من 4 من 5 … انصح فيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1425775-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdelsalam-al-sarkhi/98194/28", "user": "Abdullatif1994", "ts": 1440563325000, "tid": 98194, "pn": 28}}]}', 1440563325000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dyaa94-me311', 'stk-dyaa94', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f98194", "n": "Dr. Abdelsalam Al-Sarkhi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "152 - ME311\n\nOVERRATED\n\nللأمانة الدكتور خلوق ومتمكن من الفلود وشريح…بسسسسس\n\nاخالف اللي قالوا تصحيحه تمام…في التصحيح يعطيك اقل من حقك وتتعب اذا كان الحل صح الا الجواب الاخير بسبب غلط بسيط في الarea ولا شي ثاني…\n\nفي الفاينل مافيه شفافية الدكتور… حتى ماعطانا درجة الفاينل… القريد ع طول بالبورتل مافي حتى فرصة تراجع…بالميجيرين عطاني اقل من حقي واضطريت اروح له المكتب عشان يصصححها واتوقع الفاينل نفس الكلام…وفي النهاية القريد مو مرضي ابد …😦\n\n+ البروجكت عطا معظم السكشن 3.5 من 5 عكس اللي قالو يدف وفل مارك\n\nخلاصة الموضوع الدكتور بتتعب معاه ب التصحيح…اذا انت سلف ستدي ومو من النوع اللي يحل مليون الف مسألة عشان يجيب فل مارك بالاكزامز ما انصحك…\n\nبس اذا انت من بني دفره ولاتفارق القلم الرصاص والمسائل ويهمك بس الشرح…سجل ترا شريح واخلاق الدكتور\n\nوشكرا…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1449200-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdelsalam-al-sarkhi/98194/30", "user": "Dyaa94", "ts": 1463415097000, "tid": 98194, "pn": 30}}]}', 1463415097000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-madridista-me311', 'stk-madridista', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f98194", "n": "Dr. Abdelsalam Al-Sarkhi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME311 - 162\n\nشرح أسطوري وأخلاق وتعامل وكل شيء… لكن قريداته سييييئة\nوحتى لو كان باقيلك نص درجة عالقريد اللي بعده ماراح يزيدك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474213-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdelsalam-al-sarkhi/98194/31", "user": "Madridista", "ts": 1496198286000, "tid": 98194, "pn": 31}}]}', 1496198286000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-at_07-me311', 'stk-at_07', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f98194", "n": "Dr. Abdelsalam Al-Sarkhi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME311\n163\n\nلو ب امدح الدكتور ب اتعب وانا اكتب\nالشرح ولا الاخلاق\nكل وحده افضل من الثانيه\nالدكتور شريييييييييييح يفهم الصخر ما شاء الله تبارك الله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1480139-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdelsalam-al-sarkhi/98194/32", "user": "AT_07", "ts": 1505218722000, "tid": 98194, "pn": 32}}]}', 1505218722000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulrahman_780-me311', 'stk-abdulrahman_780', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f98194", "n": "Dr. Abdelsalam Al-Sarkhi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "semester: 171\nCourse: ME311\n\nبنود التقييم :\n\nالتحضير :\nورقة تمر على الجميع وحضر اللي تبي الدكتور مايهتم بالتحضير ولا يراجعه\nطريقة الشرح :\nسلايدات على خفيف وكتابة على السبورة مع حل امثلة من اسئلة الكتاب , مافيه احسن منه بالشرح\nالكويزات :\nمتوسطة الى سهلة ومرة جانا كوز من اولد فاينل\nالمياجر:\nكومن بس السؤال اللي يحطه الدكتور هو الاصعب\nالفاينلات :\nكومن\nالقريد النهائي:\nA\nالصوت:\nواضح\nإضافات :\n\nالدكتور يربط لك المادة بامثلة من الواقع\nمتساهل بتسليم الهوموورك\nالبروجكت حقه افرجه حول 2.5 من 5 الله يسامحه\nبالنسبة للقريدات حقك بدون زيادة او نقص", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485941-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdelsalam-al-sarkhi/98194/33", "user": "Abdulrahman_780", "ts": 1515656274000, "tid": 98194, "pn": 33}}]}', 1515656274000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_nd_m-me311', 'stk-m_nd_m', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f98194", "n": "Dr. Abdelsalam Al-Sarkhi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME311 - T172\n\nالتحضير : غالبًا ورقة تمر على الطلاب و أحيانًا ينادي الأسماء بنفسه، إذا جيت لييت (بالمعقول) ما يقولك شي، مايهتم كثير للتحضير و يسمح بالميك أب\n\nطريقة الشرح : يفتح السلايدات و يشرح الكونسبت و بعدين يبدأ حل المسائل، يحل مسائل بالهبل بأفكار و تريكات مختلفة، خلال الشرح يوجه أسئلة كيف تحل هذه؟ ايش الإيريا بالحالة هذه؟ الخ الخ\nباختصار، شــــــــــــــــــريــــــــــــــــــــــــــــــــــح ❤️\n\nالكويزات : يختبر مجموع 6 كويزات و ياخذ أفضل 3، الكلاسورك عنده أشوفه مضمون و الكويزات متوسطة الصعوبة\nالترم هذا سوا حركة أنه أختبرنا كويز يعادل كويزين، يعني إذا جبت 10 كأنك أختبرت كويزين و أخذت فيهم 10\n\nالمياجر:\nكومون\n\nالفاينلات :\nكومون\n\nالقريد النهائي:\nتقييمي للدكتور أتركه لكم، بالنسبة لتوزيع الدرجات فالأفرج عند الدكتور C+، و تاخذ حقك بالقريد لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ\n\nالصوت:\nالصوت واضح جدًا\n\nإضافات :\n\nالإيجابيات\n\nمحترم و منظم\nمرن بالحضور\nشريح و فاهم زين\nمتعاون جدًا جدًا جدًا بالحضور و الغياب و مواعيد تسليم الواجبات و المشروع و الكويزات، تهمه مصلحة الطالب\nتصحيحه جيد، مستحيل يظلمك و ممكن تاخذ أكثر من حقك\n\nالسلبيات\n\nالقريد تاخذ حقك بالملي (البعض يعتبرها سلبية، شخصيًا لا)\nمايعوض عن كلاسات أوف عن المياجر\n\nرفعت سلايدات و كويزات و سيلابس المادة ترم 172 في الريسورسيز\nKFUPM Resources v3", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1499316-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdelsalam-al-sarkhi/98194/34", "user": "M_nd_m", "ts": 1536703396000, "tid": 98194, "pn": 34}}]}', 1536703396000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ksa1990-me311', 'stk-ksa1990', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f98194", "n": "Dr. Abdelsalam Al-Sarkhi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 311\n\nللأمانه أشوف ان الدكتور Overrated\n\nالتحضير : ورقة تمر وتوقع عليها\nطريقة الشرح : متيريال ميجر 1 الشرح كان مره سيء والوضع كان ضياع بعدها من ميجر 2 للأخير ممتاز جدا\nالكويزات : كوزاته صعبه جدااااااااااااا وفيها تحدي وتكون من اسئلة اولد اقزام غالبا\nالمياجر: تصحيحه عادي تاخذ حقك ما يدف ولا شيء\nالفاينلات : نفس المياجر\nالقريد النهائي: B\nالصوت: واضح\nإضافات :\nبسوي مقارنه بسيطة مع دكتور ثاني ممتاز ويدرس نفس المادة اتمنا تكون مفيدة:\nسعد بن منصور أفضل من السرخي من ناحية الكلاس وورك (عند السرخي مستحيل تاخذ فل بينما بن منصور تقدر تاخذ فل بالراحه)\nالشرح بشكل عام ما يفرق كلهم كويسين\nالتحضير السرخي افضل سعد بن منصور يحضر اول ما يبدا الكلاس والي يتأخر ليت على طول\nالبروجيكت سعد بن منصور افضل احيانا يلغي البروجيكت واحيانا يعطي بروجيكتات سهله جدا اما السرخي عطانا بروجيكت صعب ولا طالب بالسكشن كامل أخذ فيه فل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1501872-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdelsalam-al-sarkhi/98194/35", "user": "ksa1990", "ts": 1541354509000, "tid": 98194, "pn": 35}}]}', 1541354509000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11264-me311', 'stk-user11264', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f98200", "n": "Dr. Mohammad Al-Qahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "201 - ME311\n(ترم أونلاين من أوله لآخره) - التقييم كاتبه صديقي\n\nتقسيم الدرجات كان\n50% تستات\n15% ميد تيرم\n10% اختبار ما قبل الفاينل\n25% فاينل\n\nالتحضير:\nكل كلاس عن طريق البلاك بورد أوقات ينادي بشكل عشوائي وكل غياب خصم 1% وفي حال ناداك وما رديت يزعل مره وممكن حتى يخصم أكثر من 1%.\n+ لازم تحط صورتك في البلاك كولبرت او خصم.\nعلى نهاية الترم آخر أسبوعين الحضور صار اختياري.\n\nالبونص:\nبداية الترم كان يسأل واللي يجاوب بعض الأحيان له 0.3% بونص.\n\nالشرح:\nرهيب وبالعامية نفس مقاطع اليوتيوب.\n\nالتستات:\n8 كلها عليها 6% إلا واحد 8% واغلبها ريتن على يونت او اثنين من مقاطعه، طبعا النظام تحل بورقة وترفع الحل عندك ٥د بدون كاميرا والوقت يتراوح ما بين ضيق ( بالقوة تخلص على الوقت ومع العجلة ممكن تغلط) إلى غير كافي (مستحيل تقدر تخلصه كامل وحصلت كذا مره).\nملاحظة: احد التستات كان تلخيص واحدها كان لونق تست مدته ٥ ساعات.\nطبعا في حال ما سلمت خلال ال٥ دقايق مهما كان عذرك بتاخذ صفر وحصلت على الأقل ل٧ طلاب في أحد التستات حسب كلام الدكتور يعني 0/6%.\n\nالميد تيرم:\nأول بارت كان خيارات تحل بورقة وليس عن طريق البلاكبورد نظامه كالآتي:\n\nأسئلة كونسبت وعددها قليل تختار الإجابة بدون حل.\n\nمسائل قصيرة ولازم تكتب الحل وتختار الإجابة الصحيحة، إذا شوزت صح بدون حل= صفر، وإذا شوزت غلط حتى لو فيه حل= صفر ما في بارشيل!\n\nالبارت الثاني والثالث مسائل طويلة، آخر بارت كان عبارة عن سؤال اشتقاق قال انه ما يجيب هالنوع من الاسئلة في أحد مقاطعه وهو يشرح فكره مشابهه، طبعا جابه والآفرج لذا السؤال كان 33%. افرج الميد كامل كان 57%.\n\nاختبار ما قبل الفاينل:\nكان على أكثر من نص الماتيريل خيارات بنفس نظام اول بارت من الميد لازم حل والتشويز بصفر وما في بارشيل والوقت ضيق والأفكار متنوعة وبعضها جديدة.\n\nالفاينل:\nكان على شباتر محدده والوقت جدا جدا ضيق للبارت الأول كان عبارة عن ٣ فقرات أحد الفقرات توجد hp لمعادلة فيها 8hL ، أغلبنا ما قدر يخلص إلا أول فقرة وقليل حل الثانية ، والعجيب الدكتور راسل ايميل مستغرب انه محد حل الثالثة!!! البارت الثاني كان الوقت ضييق يا دوب تخلص لو فاهم، الأخير كان فيه فكرة جديدة اشتقاق.\n\nما انصح بالدكتور ابدا ابدا خصوصا بالاون لاين (تابع مقاطعه على اليوتيوب رهيبه بس شف اي احد غيره) كنا طول الترم نخاف يفصل علينا في أي لحظة + اغلب التستات كانت ويكند ومره جمعة حتى!\n\nأكبر سلبيتين كانت:\n\n١. الوقت الضيق للتستات والميد والفاينل والمبرر (الغير منطقي) انه في النهاية آفرج بدون أي اعتبار أنه لو كان الوقت كافي لحل الامتحان كامل كان بيصير فيه تباين بالدرجات ، ممكن اول فقرة بالسؤال طويلة بس سهله للجميع والثانية هي اللي تميز بين الفاهم وغيره ! بس لا ، النظام نقلل الوقت ونقول آفرج!\n\n٢. اختباراتنا كانت بدون كاميرا يعني طبيعي واجد يغشون والآفرج مرتفع في بعض التستات، كذا مره جاب أسئلة يقولون حلولها ب chegg .\n\nما اعطانا واجبات ولا بروجكت، حول درجاتهم لتستات.\nشي طبيعي تطلع فاهم ومدرك المادة بس بقريد نازل لأنك خبصت في كم تست او حصلت مشكلة وما قدرت تسلم في ٥د.\n\nالآفرج = c للكورس، كان إجباري من القسم بحسب كلام الدكتور.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527301-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-al-qahtani/98200/39", "user": "user11264", "ts": 1609017108000, "tid": 98200, "pn": 39}}, {"id": "stk-dr-f103287", "n": "Dr. Atia Khalifa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME311 - 201\nأونلاين بالكامل\n\nالتحضير: تلقائي من البلاك بورد، ما ينادي عليك ولا شيء.\nالشرح: يشرح من سلايدات، وبالمناسبة ما يرفع سلايداته على البلاك بورد مدري ليه لكن عمومًا بتحصل وحدة شبيهة لها في الريسورسز. شرحه للأمانة ممتاز وأحيانًا كنت أشوف تسجيلاته بدل مقاطع القحطاني إذا انزنقت بالوقت بحكم أنه يعطي الزبدة عكس القحطاني يطوّل.\nالكويزات: الصعوبة متوسطة لكن الوقت أشوفه كارثة -بسبب الأونلاين طبعًا مضيّقين الوقت علينا-. دايم أكون مزنوق بالوقت ومحشور وأخلص على الحافة. عمومًا يجيب من أسئلة الكتاب أحيانًا فركزوا عليها.\nالمياجر والفاينلات: هي coordinated لكن كل دكتور يكتب أسئلته، حقتنا كانت متوسطة شوي يعني تحصّل أشياء سهلة وأشياء صعبة.\nالتصحيح وهذا لازم أخصص له نقطة منفصلة: الدكتور تصحيحه سيئ جدًا. يا صفر يا 10 ما يعرف شيء اسمه وسطيّة. للأمانة ما عجبني أبدًا أذكر آفرجنا بالميد حول ال50 أو تحتها!\nالقريد النهائي: والله احترت معاه وأترك لك التقييم. الشرح كويس لكن التصحيح لك عليه، مع العلم إن القحطاني مب مقصر بالشرح في اليوتيوب. فرأيي دورلك دكتور تصحيحه جيد وشرحه جيد عشان ترتاح باقي الترم ولا يرتفع ضغطك.\n\nإضافات:\n- الدكتور دمه خفيف بالمحاضرة وينكت ويعطيها جو\n- الإيميلات مب دايم يرد عليها، وإذا رد تحسّه يرد بالقطّارة وهالشيء يجلط صراحة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527812-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/atia-khalifa/103287/33", "user": "user11264", "ts": 1610432843000, "tid": 103287, "pn": 33}}]}', 1609017108000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sake-me311', 'stk-sake', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f98200", "n": "Dr. Mohammad Al-Qahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 311 - Term 211\n\nالتحضير: بأول الاسابيع ماكان يحضر ، بس لما مصخوها الطلاب بالغياب + درجاتهم اللي ما اعجبته ، قام يرجع يحضر ، اخر اسبوعين ماحضر فيهم كلش ، مو مرة يهتم بالتحضير.\n\nطريقة الشرح : يشرح عن طريق سلايداته وطريقة شرحه نفسها بالضبط بالمقاطع بالاضافة الى شوية تنكيت، مررة ممتازة ومفهومة وممتعة ويشرح باللغة العربية اكثر شي. اللي يفرق بالكلاسات عن المقاطع انه يخرج عن الموضوع ويقعد يسولف عن امور ثانية ، احيانا يطول واحيانا عشر دقايق بس. بعض الاحيان يجي ياخذ كل الكلاس سوالف عن مصلحتنا وهالامور ، وبعض المرات ماشرح اول عشر دقايق بسبب مزاجه السيئ.\n\nالكويزات : اخذنا خمس تيستات واخذ افضل 4 منها، كل واحد عليه 5% ، كلها متوسطة الصعوبة الا واحد قال بيكون صعب وجا صعب ، الاسئلة ماتخرج عن السلايدات. للاسف الشديد انه ماعنده مرونة بتأجيل المواعيد ، وتحديده للمواعيد اذا مو الاسوأ على الاطلاق ، دائما موعده غلط. في مرة حط تيست بعد ميجر ee204 وبنفس يوم ميجر math202 ، مارضى يأجله ، بالنهاية سوا اختبار خاص لحقين 202 فقط الاسبوع اللي بعده ، ماعرف ليش ماخلاه لنا كلنا … و احد التستات حطه بنفس موعد ميجر الثاني ل ee204+306 ، ومارضى يأجله ، ما اعرف ليش مايحطه قبل ميجر الفلويد بعدة ايام ، يزعل على درجاتنا السيئة ويقط اللوم على مذاكرتنا والسبب هو بمواعيده الغلط.\n\nالمياجر: كومن\nالفاينلات : كومن\nالصوت: واضح بلهجة مفهومة\n\nإضافات : الدكتور ملك البونصات ، عادي تجمع بونصات ترفعك قريد! بترمنا كان يطلب تلخيص لمقاطعه ، اكتبها بشكل مرتب وباستخدام الوان وارسم الرسومات واضمن لك فل بالبونص. ابدا لاتضيع بونصاته.\nالدكتور من ناحية الاخلاق عسسللل ويهتم بمصلحة الطالب وكله يضحك معنا ، ولكن ولكن ولكن ولكن ، اذا عصبه طالب، يقلب مزاجه سيئ وتكره الكلاس معه. هو يحب المجتهدين واللي يجيبون درجات ، كان يقول اني اكره كلاسكم لانكم ماتشاركون ويحب كلاس الثيرمو لانهم مشاركين ودرجاتهم عالية ، لكن بعد الميجر 2 لما صار افرجنا عالي وافرج حقين الثيرمو نازل ، قلب الوضع ههههههههه، صار يحب كلاسنا ويطقطق على حقين الثيرمو.\nالدكتور شديد جدا من ناحية الدرجات ، ولكن تاخذ حقك بالضبط حتى بالتصحيح ، واذا كنت تستاهل زيادة فبيزيدك من عيونه ، لكن اذا ماتستاهل فمانصحك تروح له ابدا. يراقب اذا في نقل وغش بالواجبات ولا لا ، حيث احد الواجبات اعطى 0 للي نقلوا.\n\nبشكل عام يحب المجتهدين والمهتمين ، حتى لو درجاتك نازلة ولكن تحضر يوميا وتهتم بيهتم فيك مرة، البروجكت اذا شاف جهد واهتمام عليه بيعطيك درجة حلوة توصل لفل ، اذا شاف تسليك بيخسفك.\nالدكتور عليه كلام كثير ، بعد الميجر الاول حسيت بالندم اني نزلت معه، لكن بعدين تغير رأيي ، كلاساته حلوة ، صير محترم معه وبيصير محترم معك ، وبونصات توصل ل6%، مافي أحلى من كذا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533292-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-al-qahtani/98200/44", "user": "SAKE", "ts": 1641305541000, "tid": 98200, "pn": 44}}]}', 1641305541000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6686-me311', 'stk-user6686', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f98202", "n": "Dr. Rashed Ben Mansour", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ما شاء الله الشباب مقيمينه بذمّة 🤠\n\nme 311\n121\n\nالتحضير :\n\nكل كلاس … العادة آخر 5 دقايق\nمهب يخالف على التاخير\nكل غياب بـ نص درجة\n\nطريقة الشرح :\n\nيفتح سلايدات بعض المرات ويحل اقزامبل\nعن نفسي ما كنت افهم عليه ابددد\nوالمادة من اول صفحة الى اخر صفحة كانت سلف ستدي بالنسبة لي\n\nالكويزات :\n\nصعبة غالبًا\nياخذ اعلى 5 كويزات\nكل كويز عليه 2%\n\nالمياجر والفاينلات : كومن وتصحيحه عادي\n\nالقريد النهائي: C مع الأب قريد 🤠\n\nالصوت: واضح … الظاهر انه جزائري او تونسي\n\nإضافات :\n\nافريجنا مهب كان بالارض وبس … الا كان تحت الارض\nلدرجة انه اخر اسبوعين عطانا 4 كويزات زود على الـ 5 اللي قبل عشان يرفعنا 🤠\n\nعندي صورة للدرجات ما قبل الفاينل وان حصل لي ان شاء الله نزلته\n\nالبروجكت كان سهالات شغلة يومين على برنامج اسمه epanet\nتحل مثالين وتسوي لهن ريبورت\n\nعلى العموم اللي بيخلي المادة سلف ستدي مهب فارق معه الدكتور", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1164990-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rashed-ben-mansour/98202/3", "user": "user6686", "ts": 1358344578000, "tid": 98202, "pn": 3}}]}', 1358344578000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulmalik1422-me311', 'stk-abdulmalik1422', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f98202", "n": "Dr. Rashed Ben Mansour", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME-311-231\nخلال ال3 سنوات ونص اللي قضيتها في الجامعة, مافيه دكتور دفعني اسوي حساب فالموقع عشان اقيمه غير الدكتور رشاد, هالدكتور بالنسبة لي هو اسوأ دكتور درسني في حياتي الأكاديمية\n\nالتحضير: توقيته عشوائي لكنه يميل الى بداية الكلاس, بعد مرور 10 دقايق يرمي لنا مسألة ويقول حلوها على مابال احضر واللي يحلها له بونص, تحضيره ورقي وينادي بالاسماء\n\nطريقة الشرح: اعفن طرق الشرح بالحياة, من بداية الكلاس الى نهايته وهو جالس عالكرسي ويشرح من السلايدات بطبقة وحده, شرحه ممّل إلى ابعد حد, في منتصف الترم يبدا يحل مسائل عن طريق اللابتوب (معاه قلم) وحتى في هذي طريقته غبية, يكون مجهز الحل عنده في ورقة ويرجع ينسخ الحل في الون نوت, مافيه اي شرح بالموضوع بس مجرد ينقل الحل ويتوقع اننا كذا بنكون فاهمين, اضف الى ذلك ان شرحه مركّز على اشياء مالها لزمة وهالدكتور يعشق انه يحل كل مسألة من الصفر وما يعترف بالاختصار واستخدام القوانين الجاهزة ولازم الى يسوي انتجريشن في كل مسألة. ففي المادة هذي دور لك مصادر شرح ثانية من بداية الترم والدكتور شايع ما يقصر\n\nالكويزات: متوسطة إلى سهلة في بعض الأحيان, دائما ماكان يجي فيها افكار جديدة لكنها ما تشكل على اللي فاهم ومذاكر صح\n\nالمياجر: كومن لكن هو الكورد, عطانا ميجرين, الأول متوسّط والثاني كان قمة السهولة\n\nالفاينل: كومن لكن مره ثانية هو الكورد, الفاينل كان تعجيزي وكل الاسألة اللي اعجزت الطلاب كان هو اللي مسويها, اقدر اقول ان الفاينل كان اصعب فاينل اختبرته في حياتي (آفرج 44)\n\nالقريد النهائي: المقصود هنا القريد اللي اعطيه انا للدكتور صح؟ اذا صح ف اعطيه F كبر راسه\n\nالصوت: ضعيف وبطبقة وحده وبلهجة فرنسية تجيب الهم, حتى لو قاعد قدامه مستحيل تقدر تنتبه معاه اكثر من دقيقتين,\n\nإضافات:\n\n- وش اضيف ووش أخلي!! هالدكتور لو تخرجي بالترم الجاي يعتمد على اني انزل عنده والله ما انزّل, بداية الترم الدكتور كان صارم من ناحية الاجهزة الإلكترونية ومن بعد اول ميجر اجبر الكلاس كامل انه ما يستخدم اي جهاز الكتروني (لا جوال ولا آيباد ولا لابتوب) الى نهاية الترم,\n\n- من ناحية التصحيح فالدكتور تصحيحه متساهل ويدف الطلاب الى ابعد حد ممكن لكن لا تفكر تناقشه لانه بيشخصنها معك\n\n- الدكتور ما يعترف بالبلاك بورد نهائياً فمن بداية الترم الى نهايته البلاك بورد كان فاضي تماما الا من سلايدات لاحد التشباتر, درجاتك في المياجر والكويزات تستلمها في الكلاس والواجبات انساها الى اخر يوم بالترم قبل ما ينزّل القريدات ذاك الوقت تشوفها\n\n- الدكتور في درجات الهوموورك كان ظالم ويعطي الدرجات بالاسم بحيث اني سلمته اكثر من هوموورك فيه اخطاء وبالنهاية عطاني انا وواحد بالسكشن فل والباقين نقصهم (رغم ان كل السكشن ناقلين الواجب من الهيروز), ف اقدر اقول انه لو اعطيته انطباع انك كويس راح يدفك بالبونص والهومووركات والاشياء اللي مافيها تصحيح\n\n- طبعاً اذا هو الكورد انسى تجيب عنده +A لانه بينزلّك فاينل يخسفك وينزل منك 9 ولا 10 درجات بعدين يقول لك ما ياخذ +A الا اللي فوق 90 (حتى لو انت اعلى واحد في التوتال)\n\n- في البروجكت قرر يخالف كل الدكاترة اللي اعطوا طلابهم مسائل وقالوا لهم حلوها, وقرر انه يخلينا نبني سفينة! ونسوي لها تحليل شامل للطفو ول مقاومة الأمواج وووو\nيعني حرفيّاً بروجكت اخذ اكثر من 15 ساعة شغل Solidworks فقط بعيداً عن الوقت اللي اخذناه في باقي الجوانب, وطبعاً ماشاركنا معلومات وبنود البروجكت الا في اخر كم اسبوع, وفي النهاية البروجكت عليه 7 درجات\n\nاعتذر اني طولت وكتبت كلام كثير لكن والله الترم مخلص له اسبوعين ومازلت شايل عليه واتمنى ان ما احد يرتكب نفس الغلطة وينزل عنده, هالدكتور قتل متعة الفلويد بالنسبة لي الله يسامحه\n\nبالنهاية احب اقول ان الدكتور هذا هو النسخة الشرّيرة من الدكتور حبيب وشكراً 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1537220-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rashed-ben-mansour/98202/10", "user": "Abdulmalik1422", "ts": 1704985792000, "tid": 98202, "pn": 10}}]}', 1704985792000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-black_light-me311', 'stk-black_light', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f98204", "n": "Dr. Wael H. Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term:112\nCourse: ME311\n\nالتحضير : بشكل دائم … ورقة يمررها بأول الكلاس (ماقد نادى الأسماء)\n\nطريقة الشرح : يبدأ بمقدمة وبعدين يبدأ بالشرح … طريقة شرحه ممتازة وواضحه كانت بالنسبة لي … ويكتب ويحل على السبورة بشكل مرتب وبالخطوات\n\nالكويزات : بعضها كان سهل ومن الأمثلة الي يشرحها… وبعضها كان صعب … وبعضها كان طويل وصعب\n\nالمياجر:كومن\n\nالفاينلات :كومن\n\nالقريد النهائي: B+\n\nالصوت: واضح جداً\n\nإضافات : الدكتور أحياناً تحس انه معصب لأن الطلاب مايتجاوبون معاه بالكلاس … ويهزيء الي يجاوب جواب سخيف … بس صار يمسك نفسه بالأخير … بشكل عام انصح انك نتزل معاه لأنك راح تفهم الـ ME311 مزبوط 🙂\nوالقريد حلو (مايدف القريد … بس يدف بالتصحيح)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1049381-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-wael-h-ahmed/98204/10", "user": "Black_Light", "ts": 1338635300000, "tid": 98204, "pn": 10}}]}', 1338635300000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-s2010xxxxx-me311', 'stk-s2010xxxxx', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f98204", "n": "Dr. Wael H. Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME311-term 131\nالتحضير :ورقة تمشي على الطلاب\n\nطريقة الشرح : سلايدات وسبورة ويعرف كيف يوصل المعلومة.\n\nالكويزات : 4 كوزات ياخذ افضل ثلاثة. ما فيها صعوبة وتركات كثيرة لانه يركز على الكونسبت.\n\nالمياجر:كومون وتصحيحه كويس. اذا شافك فاهم يدفك. يعني ما ينقصك على اغلاط تافهه.\n\nالفاينلات : كومون\n\nالقريد النهائي: A+\n\nالصوت:ممتاز واكسنت داخل فيه شوي اللهجة المصرية الـ TH ينطقها س\n\nإضافات :باخر الترم يعطي بروجكت ويصيد الطلاب اللي ينقلون من بعض ويعطيهم صفر. والبروجكت عليه 5. يعني حاول انك ما تنقل من خويك وحله بنفسك وهو بيدفك, حرام تضيع 5 درجات !\n\nويحب يطقطق على الطلاب لكن بطريقة مؤدبة وما تهين الطالب. عشان كذا بعض الطلاب ما يسال يخاف يطقطق عليه 🤣", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1316609-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-wael-h-ahmed/98204/14", "user": "s2010xxxxx", "ts": 1389096120000, "tid": 98204, "pn": 14}}]}', 1389096120000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-stu2009-me311', 'stk-stu2009', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f103287", "n": "Dr. Atia Khalifa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الماده me311 -سمستر 121\n\nبنود التقييم :\n\nالتحضير :\nيحضر يوميا ولا يهتم في التحضير يعني تحصل الغايبين عشره من الكلاس وفي الورقه واحد\nطريقة الشرح :\nيشرح النظريات وطرق الاشتقاق وبعدين يحل الاكزامبلز…وطبعا عنده سلايدات مختصر المنهج\nالكويزات :\nكويزاته سهله بس يحب يتفلسلف ويبي الحل بطريقه معينه…يعني لو كان الحل غير اللي يبيه يخصم 😐\nالمياجر:\nكومن\nالفاينلات :\nكومن\nالقريد النهائي:\nأعطيه C+\nالصوت:\nإضافات :\nالدكتور زين في الثيرمو لاكن في الفلود ابعد عنه…فوق ان شرحه مو ذاك الزود يحب يعقد في الأسئله وفوق هذا معروف عنه انه مو راعي قريد\"يعني من الاخر شوف أحد احسن منه\"", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1121588-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/atia-khalifa/103287/16", "user": "stu2009", "ts": 1353591114000, "tid": 103287, "pn": 16}}]}', 1353591114000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_91110-me311', 'stk-_91110', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f103287", "n": "Dr. Atia Khalifa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 311 - 172\n\nالتحضير :\nيمرر الورقة بعد نص ساعة تقريبا من بداية الكلاس …\nالعدد قليل عنده غالبا يعني إنسى تحضر خويك …\nما يحب التأخير - 5 دقايق أ, اكثر بشوي مسموح …\n\nطريقة الشرح :\n- الدكتور شرييييح وفاهم المادة تمام ويوصل لك المعلومة بسهولة …\n+ مجاله في الأبحاث له علاقة بالفلوبد , دايما يعطينا أمثلة واقعيه وتطبيقات تساعدك في فهم المادة وتطوير عقليتك كمهندس …\n- يشرح على سليدات عاديه ويكمل الباقي على السبورة , يحل أمثلة الكتاب ويتوسع فيها , بعض الأحيان يجيب أسئلة من آخر الكتاب أو أولد أقزامز .\n\nالكويزات :\nأربع كوزات سهلة زي أفكار الأمثلة .\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: A\n\nالصوت:\nواضح مسموع لكن على مستوى واحد ممكن يجيب لك النوم\n\nإضافات :\nالتصحيح : كثييير قالوا لي يوم سجلت معاه ( مجبور ) الله يعينك على الجزار - على حد تعبيرهم 😔\nلكن بعد ميجر ون شفت إن الدتور عادل جدا في التصحيح ويمكن يعطيك أكثر من حقك بشوي لكن عنده مشكلة تحتاج تنتبه له عشان تطلع بنتائج طيبة . الدكتور أهم حاجة عنده تجيب الحل صح حتى لو بطريقة مختلفة , لكن إذا ما فهم حلك على طووول يخسف فييك 😆\nعشان كذا أنصحك تراجعه بعد كل كويز أو ميجرر لأنه ما يرجع الأوراق عشان الطلاب يجيونه للمكتب\n\nمثال : فيه سؤال في ميجر 2 حليته بطريقة الدكتور ما فهمها عطاني 1/5 , لكن يوم جيت شرحت له عطاني 4/5 وخصم غلى الفاينل انسر بس 👏\n\nالقريد النهائي : ال A+ , قال لنا في بداية الترم للي مجموعه 90+ بغض النظر للآفرج لكن في النهاية الي مجموعه 87 أخذ A+ :in_love:\nوأعرف كم شخص تواصلوا معاه بعد الفاينل يسألون عن القريد , رد عليهم لكن يوم حطها في البورتال زادهم قريد 😁\n\nإذا نزلت معاه تحتاج تحل مسائل كثيير عشان المياجر أما الكونسبت لا تشيل همه 👍\n\nنقطة مهمة : الدكتور ما يحذف ولا حاجة ! كل الكوزات والهوموركات محسوبة يعني حسابك من بدري ولا تضيعها .\n\nلا تفكر تستخدم عنده الجوال أبدا 😆\n\nالبروجكت أعطانا مواضيع نبحث عنها وقال الي يقددم لنا عرض عن البروجكت له بونص 2 %\n+ الي عمل التقييم حق الدكتور أعطاه بونص 1%", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493358-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/atia-khalifa/103287/31", "user": "_91110", "ts": 1527734393000, "tid": 103287, "pn": 31}}]}', 1527734393000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-moh_ammed-me311', 'stk-moh_ammed', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f103287", "n": "Dr. Atia Khalifa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 311 - Term 221\n\nالتحضير: ورقة يمررها على الطلاب في منتصف وقت المحاضرة تقريبا أو نهايتها. مافيه خصم على التأخير بس أحيانا يعصب على الطلاب اللي يتأخرون، وبالنسبة للغياب أيضا مافيه خصم بس أهم شيء لاتوصل ل DN.\n\nالشرح: شرحه كله تقريبا على السبورة، وفي بعض الأحيان يستعين بالسلايدات لتوضيح بعض الأمور. شرحه كويس عموما.\n\nالصوت: غالبا يتكلم بالعربي.\n\nالكويزات: عطانا 3 كويزات بس، عشان كذا الويت عليها عالي. مستواها غالبا سهل إلى متوسط (إذا مذاكر بتحل).\n\nالتصحيح: بصراحة أشوفه متشدد أحيانا في التصحيح، ممكن تغلط في أشياء غير مقصودة (مثلا إنك تعوض غلط في القانون) ويخصم عليك.\n\nإضافات:\n* الدكتور - الله يهديه - مايجاوبك إجابة شافية إذا جيت تسأله أو تناقشه في موضوع معين، مثلا: مرة كنت اسأله إذا الدرس الفلاني معنا ولا لا وما أعطاني إجابة واضحة، وكذلك تحسه مو دايم يتجاوب مع الطلاب.\n\nالقريد النهائي: C+ (عادي ومو مرة سيء)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536120-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/atia-khalifa/103287/34", "user": "Moh_ammed", "ts": 1673027492000, "tid": 103287, "pn": 34}}]}', 1673027492000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5969-me311', 'stk-user5969', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f118632", "n": "Dr. Saad Mansoor", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا ادرس عنده me311 هالترم\nالدكتور مرره ممتاز وكوزاته جدا سهله وقليله\nويحضر اخر الكلاس حتى لو جيت متاخر نص ساعه مايقول لك شي\nوشررريح وتصحيحه في المياجر مره حلو يعطيك حقك وزياده\nيعني اذا لقيته سجل عنده وانت مغمض\nانا ناوي اسجل عنده me315 ان شاء الله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1131437-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saad-mansoor/118632/6", "user": "user5969", "ts": 1354639697000, "tid": 118632, "pn": 6}}]}', 1354639697000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmad1-me311', 'stk-ahmad1', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f118632", "n": "Dr. Saad Mansoor", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "me 311 term 121\nبنود التقييم :\n\nالتحضير : يحضر نهاية الكلاس\n\nطريقة الشرح : ممتاز على السبورة\nبس بعض الاحيان يقعد حصة كامله يعلمك كيف اشتقينا القانون\nولكن يعوضها بالكلاس اللي بعده يحل مسائل\nالكويزات :\nقليله جدا جدا جدا\nباقي على نهاية السمستر خمس اسابيع ولين الان فقط كوزين !\nولكن سهله\nالمياجر:\nكومن\nالفاينلات :\nكزمن\nالقريد النهائي: لسا مابعد\nالصوت: ممتاز\nإضافات :\nجينا هنا\nالدكتور تصحيحه حلو جدا\nولكن افرج سكاشنه مرتفع جدا\nمثلا افرج سكشنه الان اللي انا فيه الظاهر 65\n\nافرج مدرس ثاني 52", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1131487-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saad-mansoor/118632/8", "user": "AhMaD1", "ts": 1354643006000, "tid": 118632, "pn": 8}}]}', 1354643006000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kfupmer2014-me311', 'stk-kfupmer2014', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f118632", "n": "Dr. Saad Mansoor", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term: 181\n\nME311\n\nالتحضير : في اول ثانية في الكلاس\n\nتتأخر يعطيك ليت\n\nواذا عندك سبب مقنع تقول له بداية السمستر ويصير مايحط لك ليت ابدا\n\nطريقة الشرح :\n\nممتاز بس يشرح الكونسبت كثير والديرايفيشن يطول فيه وكلامه كثير الزبدة\n\nالكويزات :\n\nسهلة\n\nعطانا ٣ واخذ افضل ٢\n\nالمياجر:كومون\n\nالفاينلات : كومون\n\nالقريد النهائي للدكتور: B+\n\nالصوت: واضح جدا\n\nإضافات :\n\nالسلبيات\n\n١- الدكتور يتكلم من اول ثانية الى اخر ثانية بالكلاس ومافيه ولا يوم واحد اوف\n\n٢- يطول جدا في تسليم الدرجات\nالميجر الاول اخذ له ثلاث اسابيع\nوالثاني اخذ له ٤ -٥ اسابيع\n\n٣- تصحيحه شديييييدددد يبيه نفس الطريقة اللي يبغاها بالضبط\n\nانا جبت له الجواب صحيح عطاني نص الدرجة عشان مو نفس الخطوات الي يبغاها ورحت له بالاوفيس ورفض يزودني الا بالموت زودني فيها درجة من اصل ٦ درجات\n\nالايجابيات\n\n١- يحذف غيابين بس واثنين ليت والغياب الي بعده ب نص درجة ع كل غياب\n\n٢- الكويزات سهلة وتاخذ فل في الكلاسوورك\n\n٣- حذف البروجيكت بس ماادري كيف وزّع درجاتها\n\n٤- يزود في القريد في النهاية كثييير\n\nانا اخذت 62.8 في المجموع وعطاني سي بلس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504161-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saad-mansoor/118632/27", "user": "KFUPMer2014", "ts": 1545935795000, "tid": 118632, "pn": 27}}]}', 1545935795000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-illusions-me311', 'stk-illusions', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f118632", "n": "Dr. Saad Mansoor", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 311\nTERM:181\n\nالتحضير : اول ثانية بالكلاس وبعدها ليت لو تحب السماء ما يغيره , الا اخر يمكن ثلاث اسابيع بدا يحضر بوسط الوقت.\n\nطريقة الشرح : على السبورة بشكل عام اشوفه من الكويسين بالجامعة كشرح , بداية الكورس بتزهق معاه من الدريفيشن والكونسبت الي ما ينفهم وعلى قولته يقول اي شي جديد عليك لازم تعرف الدرفيشن حقه عشان تعرف من وين جاء فبيغثك فيها وبتحس انك ضايع مررره ! بنص الكورس صار شرحه اسطوري ويحل مسائل باغلبه , بنهاية الكورس رجع شوي زي بدايته.\n\nالكويزات : 3 وياخذ اعلى اثنين , اخر واحد كان هدية بمعنى الكلمة اما الاثنين الباقيين ما كانوا سهلين للامانة.\n\nالمياجر: كومن وتصحيحه اسوأ دكتور شفته بحياتي يصحح , وحتى لو راجعته وانت واثق مليون بالمية انك صح وانه ظالمك ما فيه امل تطلع بربع درجة , لدرجة خاصم علي بسؤال ويوم قلت له هذي بالمانوال عليها درجة وانت ما عطيتني اياها قال لي بالحرف الواحد “المانوال يمشي عليه الي يبي من الدكاتره , انا امشي على الي اشوفه مهم واحط عليه الدرجة بكيفي” !\n\nالفاينلات :كومن وزي المياجر\n\nالقريد النهائي للدكتور: C عشان شرحه بس , ولا غيره ماش\n\nالصوت: واضح ولهجته مفهومة\n\nإضافات : الدكتور بالشرح من افضل الي درسوني بالجامعة , بس بالتصحيح مب من اسوأ الي درسوني الا اسوأ واحد بلا منازع , من ناحية القريد لا يزيد ولا شي انا مجموعي 61,8 وطلعت بسي ! فما اشوف انه زادني شي , شغلة ثانية يمكن تعتبر ميزة وهي انه حذف البروجكت وقال لنا بوزعه على الكويزات والمياجر والفاينل , بس يحذفه عليك ويدقك بالتصحيح للامور هذي وش استفدنا , لو هو مخليه احسن. بشكل عام مب سيء ولا هو زين , بس اشوف اذا انت طالب افرج ولا تعرف تشبك ابعد عنه ورح لاحد ثاني احسن لك , لانه ما ينفع معه ويستانس مره الا الي يجيب كل الاسئلة بالضبط زي ما يبي بالمياجر ولا بيخصم مع كل مكان .\n\nغير كذا بالكلاس معي حوالي عشرة اقل مني كدرجة من 100 من اصل حول 33 طالب , يعني حول عشرة سي وتحت 😞", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504165-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saad-mansoor/118632/28", "user": "ILLUSIONS", "ts": 1545954088000, "tid": 118632, "pn": 28}}]}', 1545954088000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11372-me311', 'stk-user11372', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f118632", "n": "Dr. Saad Mansoor", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME311 - 221 Fluid Mechanics\n\nالتحضير : تحضير الدكتور بداية كل كلاس يحضر وبعد دقيقتين يعتبر Late ومايعطي ابسنت دامك حضرت , اذا كان قبل معك كلاس بعيد بتعاني من ناحية Late وللمعلومية يوجد 2 فري ابسنت و ليت واحد مجاني\n\nطريقة الشرح : شرح الدكتور جيد للامانه لكن مشكلته ان الكلاس كامل مايوقف كلام او يعطي مهلة لاعادة التركيز الكلاس 50 دقيقة كاملة عبارة عن كلام بدون لحظة نفس , لكن كشرح جيد وتفهم معه اذا ركزت\n\nالكويزات : الكويزات لهذا الترم كانت غير عن اللي قبل وصارت على البلاك بورد عبارة عن 3 او 4 اسئلة خيارات بدون بارشل , ميزتها غالبا الدكتور يجيب للسنوات الماضية نفس الكويزات موجودة بالريسورس وللسكشن اللي قبل في حال يدرس سكشنين لكن هي كعموما مو صعبة ومستواها جيد اذا مذاكر\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nتقييمي النهائي للدكتور : B+\n\nالصوت: ممتاز وواضح\n\nإضافات : الدكتور متساعد كان بالبروجكت للامانه اتوقع اي شخص سلم الشغل عطاه فل\nفيه مشكلة بسيطة بالتصحيح حقاني للامانه جدا يعني لازم خطوات واتباع وشرح واضح اذا بتحل مافيه مجال للاختصار والقريدات برضوا جدا حقاني", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536128-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saad-mansoor/118632/32", "user": "user11372", "ts": 1673081728000, "tid": 118632, "pn": 32}}]}', 1673081728000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11848-me311', 'stk-user11848', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f118642", "n": "Dr. Abdullah Al-Sharafi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME - 311\n\nالتحضير : يوميا\nطريقة الشرح : من سلايداته الاسطورية\nالكويزات : متوسطة الى سهلة\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: A\nالصوت: واضح ومفهوم\nإضافات : الدكتور شرّيح جدا وسلايداته بطلة , متفهم بالاسئلة وما يعصب اذا سألته ويفهمك حبة حبة , الدكتور تحس معه انك فاهم الكونسبت من واقع الحياة وتستمتع معه وبالنسبة للاسئلة فيفهمك ويشرح خطوة خطوة\nالدكتور ما يتعوض", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526005-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdullah-al-sharafi/118642/6", "user": "user11848", "ts": 1601633226000, "tid": 118642, "pn": 6}}]}', 1601633226000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10610-me311', 'stk-user10610', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f118642", "n": "Dr. Abdullah Al-Sharafi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME311-201\nالدراسة كلها كانت أونلاين\n\nالتحضير :\nبداية الكلاس بالضببببط يبدا يحضر بالاسماء, ينتهي الكلاس ويشرح كم دقيقه زيادة وبعدها تكلمة إذا متأخرو الكلاس بالزوم يعرف متى دخلت\nطريقة الشرح :\nسلايداته رووووعه ولا غلطه , ذاكرها وتكفيك ولا تتابع قناة القحطاني ولاشي(اذا فاضي وتبي معلومات زيادة رح القناة ) https://www.youtube.com/channel/UChptJuGYNMcpmCW-zhTP3kg/playlists?view=50&sort=dd&shelf_id=1\nالكويزات :\nصراحة كانت كثير شوي وغالبيتها في الليل وأحيانا الويكند تقريبا 10 كوزات في الترم ,متوسطة إلى صعبة والتصحيح شدييييد\nالمياجر:\nميدتيرم عليه 15% و ونفس الكوزات بس أطول شوي\nالصوت:\nوااااضح ومتقبل للأسئلة ويناشقك ويفهمك عادي, ومررره فاهم ما شاء الله عليه\nإضافات :\nاذا تبي تفهم نزل عنده , اذا تبي قريد بتتعب عشانه شوي لان متطلبات كثير وتصحيح شديد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527503-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdullah-al-sharafi/118642/7", "user": "user10610", "ts": 1609611881000, "tid": 118642, "pn": 7}}]}', 1609611881000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-omar_ali_bajabaau-me311', 'stk-omar_ali_bajabaau', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f118642", "n": "Dr. Abdullah Al-Sharafi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME311 - 201\n(Online)\n\nالتحضير : تحضير بداية الكلاس ومتشدد لكن اذا تاخرت كثير لازم تقله السبب واحيانا يعطيك حاضر او ليت على حسب السبب. لكن اذا غبت لازم عذر رسمي.\n\nطريقة الشرح : الشرح من سلايداته الممتازة. شريح ماشاء الله عليه وفاهم ويحب يجيب امثلة تساعد ع الفهم.\n\nالتصحيح: حقاني وحسيت انه يعتمد على حسب آفرج الكلاس، بحيث انه يصير متشدد اذا الافرج عالي وكريم اذا الافرج نازل.\n\nالكويزات : كويزاته سهلة وكانت سؤال او سؤالين مقالي واحيانا معاها خيارات. في رايي تكفي مذاكرة سلايداته للكويز. الميزة انه يحاول يعطي كويزات كثيرة عشان الطالب مايتاثر كثير اذا خبص في كويز.\n\nالمياجر: ميدين من الدكتور نفسه وكانوا متوسطة الصعوبة.\n\nالفاينلات : من الدكتور وكان صراحة صعب بسبب انه افرج الكلاس كان عالي. وهو اصلا قالنا انه الفاينل بيكون صعب\n\nالصوت: صوته واضح جدا ولهجة ايضا مفهومة\n\nإضافات : الدكتور يسال اسئلة للطلاب ويحط عليها درجات عشان يحفز الطلاب على المشاركة. الدكتور يحببك في المادة ويحاول دايما يربطها مع التطبيقات والواقع وحبوب وطيب لأبعد الحدود ومتعاون ومهتم جدا لفهم الطالب ويحب الطلاب المهتمين والي يشاركون دايما ويسالون وقت الكلاس. اذا انت طالب مهتم من ناحية انك تفهم المادة ومستعد انك تبذل جهد، هذا الدكتور المناسب لك، لكن اذا انت تبغا تروق وتبغا قريد فاانصحك لا تسجل؛ لانه بيكرفك من ناحية البروجكت والكويزات.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527547-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdullah-al-sharafi/118642/8", "user": "Omar_Ali_BajabaaU", "ts": 1609763921000, "tid": 118642, "pn": 8}}]}', 1609763921000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-trad-me311', 'stk-trad', 'ME 311', 'doc', '{"docs": [{"id": "stk-dr-f118642", "n": "Dr. Abdullah Al-Sharafi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(ME311-Term 201 (Online\n\nالتحضير :\nبداية المحاضرة على طول مايتاخر دقيقة , يعرض الكشف قدامك وينادي بالاسماء ومن ناحية التاخير ممكن يسمح لك 10 دقايق تتاخرويحضرك عادي بس لاتفلها واجد\n\nطريقة الشرح :\nيشرح من سلايداته, سلايداته مرتبة جدا وممتازة جدا للمذاكرة. شرحه ممتاز ويوصل لك المعلومة بطريقة جميلة وكان لازم يخلي الطلاب يشاركون معه\n\nالكويزات :\nسهلة الى متوسطة الصعوبة , اغلبها اسالة مشابهة لامثلة موجودة بالسلايدات وطبعا كان يخلي اغلبها ريتن عشان يعطينا بارشل كريدت\n\nالمياجر:\nالميد تيرم هو سواه وكان سهل ماعدا سوال واحد كان صعب شوي , وعطانا 4 تستات بسيطة ماهي صعبة\n\nالفاينلات :\nمن عنده والصراحة كان جلد واعتقد ان السبب هو الافرج عالي, اسالة الفاينل بعضها كان متوسط لكن الوقت كان جددددددداااا ضييييق يادوب تفهم السوال وتحل والشي ذا يزعل والله لانه اثر بشكل سلبي على اغلب الطلاب وضيع علي القريد اللي كنت ابيه مع اني كنت قريب مرة\n\nالقريد النهائي: +B\n\nالصوت: واضح ومسموع\n\nإضافات : الدكتور متعاون واخلاقه عالية وحريص جدا على فهم الطالب ويحببك في المادة, تصحيحة بالنسبة لي كان جيد لكن بعض الطلاب يقولون انه ظلمهم, طبعا من السلبيات انه كان ياخذ وقت زيادة برا المحاضرة توصل ل 5 دقايق تقريبا , اخر السمستر مدري شفيه تغير علينا صار عصبي نوع ما ومعاد يقبل النقاش . مثل ماقال الاخ الفاضل اللي قبلي الدكتور كريف نوع ما فاذا تبي تروق وتبي قريد لاتنزل عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527627-me311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdullah-al-sharafi/118642/9", "user": "Trad", "ts": 1609863830000, "tid": 118642, "pn": 9}}]}', 1609863830000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
